// Sequence-diagram-local per-connection state and time accessors (parity/sequence-diagram.md §3.5.1, §8.2).
//
// qvis stored these on the model objects (`connection.qvis.sequencediagram.{generatedSibling, manualTimeOffset}`) and
// mutated the shared event parser for the "dragons" reference-time repair (SQ19). The port keeps them in WeakMaps
// owned by this view, so other views never see them:
//
// - generatedSibling: original <-> auto-generated mirror trace (both directions), reused on later renders.
// - rememberedOffset: the latency offset of a right-hand trace (computed or user-entered), keyed by its connection,
//   with an explicit `userSet` flag (SQ5 FIX: a user-entered 0 is kept).
// - refTimeOverride: the "dragons" reference-time repair, applied only through this module's accessors (SQ19 FIX).

import type { QlogConnection } from "@/model/QlogConnection";
import type { QlogEvent } from "@/model/QlogEvent";
import { TimeTrackingMethod } from "@/model/time";

const generatedSiblings = new WeakMap<QlogConnection, QlogConnection>();
const rememberedOffsets = new WeakMap<QlogConnection, { value: number; userSet: boolean }>();
const refTimeOverrides = new WeakMap<QlogConnection, number>();

export function getGeneratedSibling(c: QlogConnection): QlogConnection | undefined {
    return generatedSiblings.get(c);
}

export function setGeneratedSiblings(original: QlogConnection, generated: QlogConnection): void {
    generatedSiblings.set(original, generated);
    generatedSiblings.set(generated, original);
}

export function getRememberedOffset(c: QlogConnection): { value: number; userSet: boolean } | undefined {
    return rememberedOffsets.get(c);
}

export function rememberOffset(c: QlogConnection, value: number, userSet: boolean): void {
    rememberedOffsets.set(c, { value, userSet });
}

/** The local reference-time override of `c` (a generated mirror shares its original's, as qvis's shared parser did). */
export function getRefTimeOverride(c: QlogConnection): number | undefined {
    const own = refTimeOverrides.get(c);
    if (own !== undefined) return own;
    if (c.wasAutoGenerated) {
        const sibling = generatedSiblings.get(c);
        if (sibling !== undefined) return refTimeOverrides.get(sibling);
    }
    return undefined;
}

/** qvis `getEventParser().setReferenceTime(ms)`, view-local. Only meaningful for RELATIVE_TIME connections. */
export function setRefTimeOverride(c: QlogConnection, ms: number): void {
    if (c.timing.getTimeTrackingMethod() !== TimeTrackingMethod.RELATIVE_TIME) return;
    refTimeOverrides.set(c, ms);
}

/** qvis `getEventParser().getAbsoluteStartTime()` with the local override. */
export function absoluteStartTime(c: QlogConnection): number {
    const o = getRefTimeOverride(c);
    return o !== undefined ? o : c.timing.getAbsoluteStartTime();
}

/** Amount added to `QlogEvent.absoluteTime` for events of `c` (0 without an override). */
export function absoluteTimeShift(c: QlogConnection): number {
    const o = getRefTimeOverride(c);
    return o !== undefined ? o - c.timing.getAbsoluteStartTime() : 0;
}

/** qvis `parseEvent(e).absoluteTime` with the local override. */
export function absoluteTime(e: QlogEvent): number {
    return e.absoluteTime + absoluteTimeShift(e.conn);
}

/** qvis: `getAbsoluteStartTime() === 0 && getTimeTrackingMethod() === RELATIVE_TIME` (case U before any override). */
export function isRelativeWithoutReference(c: QlogConnection): boolean {
    return absoluteStartTime(c) === 0 && c.timing.getTimeTrackingMethod() === TimeTrackingMethod.RELATIVE_TIME;
}

/** Test helper: forget the state of `connections`. */
export function resetSequenceStateForTests(...connections: QlogConnection[]): void {
    for (const c of connections) {
        generatedSiblings.delete(c);
        rememberedOffsets.delete(c);
        refTimeOverrides.delete(c);
    }
}
